-- Nonsecret provider facts, not a secret store or execution authority.
SET ROLE hub2_authz_owner;
CREATE TABLE authz.provider_capabilities62(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL,provider_id text NOT NULL CHECK(length(provider_id)BETWEEN 1 AND 200),area_id uuid,
 revision bigint NOT NULL CHECK(revision>0),facts jsonb NOT NULL CHECK(jsonb_typeof(facts)='object'),
 actor_id uuid,client_id uuid,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(project_id,provider_id));
CREATE TABLE authz.provider_capability_history62(
 capability_id uuid NOT NULL REFERENCES authz.provider_capabilities62(id),revision bigint NOT NULL,snapshot jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(capability_id,revision));
REVOKE ALL ON authz.provider_capabilities62,authz.provider_capability_history62 FROM PUBLIC,hub2_hufu,hub2_mem,hub2_v8,hub2_worker;
CREATE FUNCTION authz.provider_metadata_safe62(value jsonb)RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$
DECLARE k text;v jsonb;s text;
BEGIN
 IF jsonb_typeof(value)='object'THEN FOR k,v IN SELECT kv.key,kv.value FROM jsonb_each(value)kv LOOP
  IF lower(k)IN('password','secret','secret_key','secret_access_key','secret_id','access_key_id','private_key','token','private_token','root_token','session_token','bearer','credential_value')OR (lower(k)='key' AND NOT(value?'provider'AND value?'bucket'AND jsonb_typeof(v)='string')) OR NOT authz.provider_metadata_safe62(v)THEN RETURN false;END IF;
 END LOOP;
 ELSIF jsonb_typeof(value)='array'THEN FOR v IN SELECT * FROM jsonb_array_elements(value)LOOP IF NOT authz.provider_metadata_safe62(v)THEN RETURN false;END IF;END LOOP;
 ELSIF jsonb_typeof(value)='string'THEN s:=value#>>'{}';IF s~'AKID[A-Za-z0-9]{16,}|-----BEGIN ([A-Z ]*)PRIVATE KEY-----|(^|[[:space:]])(s\.[A-Za-z0-9_-]{20,}|hub2_[A-Za-z0-9_-]{30,}|sk-[A-Za-z0-9_-]{20,}|st-[A-Za-z0-9_-]{20,})'THEN RETURN false;END IF;
 END IF;RETURN true;
END $$;
CREATE FUNCTION authz.provider_catalog_guard62(p_hash text,p_project uuid,p_area uuid,write_mode boolean)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE identity jsonb;actor uuid;client uuid;credential uuid;pr record;q record;action text;allowed boolean:=false;r jsonb;
BEGIN
 IF authz.runtime_role()<>'hub2_hufu'OR p_project IS NULL THEN RAISE EXCEPTION 'provider_catalog_forbidden' USING ERRCODE='42501';END IF;
 identity:=authz.authenticate(p_hash);actor:=(identity->>'actor_id')::uuid;client:=(identity->>'client_id')::uuid;credential:=(identity->>'credential_id')::uuid;
 r:=jsonb_strip_nulls(jsonb_build_object('project_id',p_project,'area_id',p_area));PERFORM authz.lock_resources(actor,client,credential,jsonb_build_array(r));identity:=authz.authenticate(p_hash);
 SELECT * INTO pr FROM v8.projects WHERE id=p_project;
 action:=CASE WHEN write_mode THEN 'resource.write'ELSE 'resource.read'END;
 IF pr.id IS NULL OR pr.state IS DISTINCT FROM 'active'OR pr.organization_id IS DISTINCT FROM(identity->>'organization_id')::uuid
 OR NOT EXISTS(SELECT FROM authz.principals WHERE id=actor AND kind='member'AND active)
 OR NOT EXISTS(SELECT FROM authz.clients WHERE id=client AND principal_id=actor AND active AND action=ANY(actions))
 OR(p_area IS NOT NULL AND NOT EXISTS(SELECT FROM authz.resource_areas WHERE id=p_area AND project_id=p_project AND active))THEN RAISE EXCEPTION 'provider_catalog_forbidden' USING ERRCODE='42501';END IF;
 -- A real project owner/manager is current management authority, never a label.
 allowed:=actor=pr.manager_id OR(pr.visibility='personal'AND actor=pr.owner_id);
 IF NOT allowed THEN
  FOR q IN SELECT * FROM authz.qualifications WHERE principal_id=actor AND project_id=p_project ORDER BY id LOOP
   IF write_mode THEN
    IF action=ANY(q.actions)AND authz.management_valid(q.id,actor,p_project)AND authz.selector_matches(q.resource_selector,p_project,r)THEN allowed:=true;EXIT;END IF;
   ELSIF authz.qualification_deadline(q.id,actor,p_project,action,r)IS NOT NULL THEN allowed:=true;EXIT;
   END IF;
  END LOOP;
 END IF;
 IF NOT allowed THEN RAISE EXCEPTION 'provider_catalog_scope_denied' USING ERRCODE='42501';END IF;
 RETURN identity;
END $$;
CREATE FUNCTION authz.provider_capabilities_read(p_hash text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE c authz.provider_capabilities62;identity jsonb;pid uuid;aid uuid;
BEGIN
 IF b IS NULL OR jsonb_typeof(b)<>'object'OR b-ARRAY['project_id','provider_id','area_id']<>'{}'::jsonb OR NOT b?&ARRAY['project_id','provider_id']THEN RAISE EXCEPTION 'provider_catalog_invalid';END IF;
 pid:=(b->>'project_id')::uuid;
 SELECT * INTO c FROM authz.provider_capabilities62 WHERE project_id=pid AND provider_id=b->>'provider_id';
 aid:=CASE WHEN c.id IS NOT NULL THEN c.area_id ELSE(b->>'area_id')::uuid END;
 IF b?'area_id'AND(b->>'area_id')::uuid IS DISTINCT FROM aid THEN RAISE EXCEPTION 'provider_catalog_scope_mismatch' USING ERRCODE='42501';END IF;
 identity:=authz.provider_catalog_guard62(p_hash,pid,aid,false);
 SELECT * INTO c FROM authz.provider_capabilities62 WHERE project_id=pid AND provider_id=b->>'provider_id'FOR SHARE;
 IF c.id IS NOT NULL THEN identity:=authz.provider_catalog_guard62(p_hash,pid,c.area_id,false);END IF;
 IF c.id IS NULL THEN RETURN jsonb_build_object('state','not_registered','project_id',pid,'provider_id',b->>'provider_id','revision',0,'execution_permission_granted',false);END IF;
 RETURN to_jsonb(c)||jsonb_build_object('state','registered_facts','execution_permission_granted',false,'plaintext_credential_returned',false);
END $$;
CREATE FUNCTION authz.provider_capabilities_store(p_hash text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE c authz.provider_capabilities62;oldarea uuid;identity jsonb;pid uuid;aid uuid;expected bigint;facts jsonb;
BEGIN
 IF b IS NULL OR jsonb_typeof(b)<>'object'OR b-ARRAY['project_id','provider_id','area_id','expected_revision','facts']<>'{}'::jsonb OR NOT b?&ARRAY['project_id','provider_id','expected_revision','facts']OR jsonb_typeof(b->'facts')IS DISTINCT FROM 'object'OR length(b->>'provider_id')NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'provider_catalog_invalid';END IF;
 pid:=(b->>'project_id')::uuid;aid:=(b->>'area_id')::uuid;expected:=(b->>'expected_revision')::bigint;facts:=b->'facts';
 IF expected IS NULL OR expected<0 OR NOT authz.provider_metadata_safe62(facts)THEN RAISE EXCEPTION 'provider_catalog_nonsecret_metadata_required';END IF;
 identity:=authz.provider_catalog_guard62(p_hash,pid,aid,true);
 PERFORM pg_advisory_xact_lock(hashtextextended('provider_catalog:'||pid::text||':'||(b->>'provider_id'),0));
 SELECT * INTO c FROM authz.provider_capabilities62 WHERE project_id=pid AND provider_id=b->>'provider_id'FOR UPDATE;
 IF c.id IS NOT NULL AND c.area_id IS DISTINCT FROM aid THEN PERFORM authz.provider_catalog_guard62(p_hash,pid,c.area_id,true);END IF;
 IF coalesce(c.revision,0)<>expected THEN RAISE EXCEPTION 'provider_catalog_revision_conflict' USING ERRCODE='40001';END IF;
 INSERT INTO authz.provider_capabilities62(project_id,provider_id,area_id,revision,facts,actor_id,client_id)VALUES(pid,b->>'provider_id',aid,expected+1,facts,(identity->>'actor_id')::uuid,(identity->>'client_id')::uuid)
 ON CONFLICT(project_id,provider_id)DO UPDATE SET area_id=excluded.area_id,revision=excluded.revision,facts=excluded.facts,actor_id=excluded.actor_id,client_id=excluded.client_id,updated_at=clock_timestamp()RETURNING * INTO c;
 INSERT INTO authz.provider_capability_history62(capability_id,revision,snapshot)VALUES(c.id,c.revision,to_jsonb(c));
 INSERT INTO evidence.audit(actor_id,client_id,domain,action,aggregate_id,revision,details)VALUES(c.actor_id,c.client_id,'hufu','provider.capabilities.store',c.id,c.revision,jsonb_build_object('project_id',pid,'provider_id',c.provider_id,'area_id',aid,'execution_permission_granted',false));
 INSERT INTO evidence.outbox(domain,aggregate_id,aggregate_revision,event_type,project_id,payload)VALUES('hufu',c.id,c.revision,'provider.capabilities.changed',pid,jsonb_build_object('provider_id',c.provider_id,'revision',c.revision,'area_id',aid,'execution_permission_granted',false));
 RETURN to_jsonb(c)||jsonb_build_object('state','stored','execution_permission_granted',false,'plaintext_credential_returned',false);
END $$;
REVOKE ALL ON FUNCTION authz.provider_metadata_safe62(jsonb),authz.provider_catalog_guard62(text,uuid,uuid,boolean),authz.provider_capabilities_read(text,jsonb),authz.provider_capabilities_store(text,jsonb)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION authz.provider_capabilities_read(text,jsonb),authz.provider_capabilities_store(text,jsonb)TO hub2_hufu;
RESET ROLE;

SET ROLE hub2_authz_owner;
